// ---------- putting products on a shelf level ----------
FIX.STACK = ['can', 'box', 'cup', 'tin', 'tub', 'giftbox', 'tofu', 'cupsq', 'icecup', 'natto', 'tp', 'book'];
FIX.SEASON_FILL = ['w_sandal', 'w_hat', 'umbrella', 'kairo', 'katori', 't_hanabi', 't_kite', 'tenugui_wave', 'battery'];
FIX.short = n => n.replace(/[（(].*?[)）]/g, '').replace(/\s*\d+(ml|L|g|kg|個|本|こ|枚|尾|パック|袋|束|ロール|箱|房)?$/, '').slice(0, 9);
// F: face frame { x0, z0, ry }; lv: { y, h, fz (front edge), d (depth), xa, xb, maxRows, tilt }
